#include <iostream>
#include <string>
​
// 统计字符串中的文本数量
int countStatements(const std::string& script) {
    int statementCount = 0;
    bool insideString = false;
    bool insideComment = false;
    char stringQuote = 0;
    bool currentStatementEmpty = true;
​
    for (size_t i = 0; i < script.length(); ++i) {
        char current = script[i];
        char next = (i + 1 < script.length()) ? script[i + 1] : '\0';
​
        // 注释块处理：如果在注释中，直到换行才结束注释
        if (insideComment) {
            if (current == '\n') {
                insideComment = false;
            }
            continue;
        }
​
        // 如果遇到 "--"，且不在字符串中，进入注释模式
        if (!insideString && current == '-' && next == '-') {
            insideComment = true;
            i++; // 跳过第二个 '-'
            continue;
        }
​
        // 进入字符串模式（单引号或双引号）
        if (!insideString && (current == '\'' || current == '\"')) {
            insideString = true;
            stringQuote = current;
            currentStatementEmpty = false;
            continue;
        }
​
        // 字符串结束处理（注意转义引号）
        if (insideString && current == stringQuote) {
            // 前面是转移字符
            if (script[i-1] == stringQuote) {
                i++; // 转义引号，跳过
            } else {
                insideString = false;
            }
            continue;
        }
​
        // 遇到分号，标记为一条语句结束
        if (!insideString && current == ';') {
            if (!currentStatementEmpty) {
                statementCount++;
                currentStatementEmpty = true;
            }
            continue;
        }
​
        // 非空白字符表示当前语句非空
        if (!insideString && !isspace(current)) {
            currentStatementEmpty = false;
        }
    }
​
    // 如果末尾没有分号，也算一条语句
    if (!currentStatementEmpty) {
        statementCount++;
    }
​
    return statementCount;
}
​
int main() {
    std::string script, line;
    while (std::getline(std::cin, line)) {
        script += line + "\n";
    }
    std::cout << countStatements(script) << std::endl;
    return 0;
}
