package main
​
import (
    "bufio"
    "fmt"
    "io"
    "os"
    "strings"
    "unicode"
)
​
// 统计字符串中的语句数量
func countStatements(script string) int {
    statementCount := 0
    insideString := false
    insideComment := false
    var stringQuote rune
    currentStatementEmpty := true
    runes := []rune(script)
​
    for i := 0; i < len(runes); i++ {
        current := runes[i]
        var next rune
        if i+1 < len(runes) {
            next = runes[i+1]
        } else {
            next = 0
        }
​
        // 注释块处理：如果在注释中，直到换行才结束注释
        if insideComment {
            if current == '\n' {
                insideComment = false
            }
            continue
        }
​
        // 遇到 "--"，且不在字符串中，进入注释模式
        if !insideString && current == '-' && next == '-' {
            insideComment = true
            i++ // 跳过第二个 '-'
            continue
        }
​
        // 进入字符串模式（单引号或双引号）
        if !insideString && (current == '\'' || current == '"') {
            insideString = true
            stringQuote = current
            currentStatementEmpty = false
            continue
        }
​
        // 字符串结束处理（注意转义引号）
        if insideString && current == stringQuote {
            if i > 0 && runes[i-1] == stringQuote {
                i++ // 转义引号，跳过
            } else {
                insideString = false
            }
            continue
        }
​
        // 遇到分号，标记为一条语句结束
        if !insideString && current == ';' {
            if !currentStatementEmpty {
                statementCount++
                currentStatementEmpty = true
            }
            continue
        }
​
        // 非空白字符表示当前语句非空
        if !insideString && !unicode.IsSpace(current) {
            currentStatementEmpty = false
        }
    }
​
    // 如果末尾没有分号，也算一条语句
    if !currentStatementEmpty {
        statementCount++
    }
​
    return statementCount
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    var builder strings.Builder
    for {
        line, err := reader.ReadString('\n')
        builder.WriteString(line)
        if err == io.EOF {
            break
        }
    }
    fmt.Println(countStatements(builder.String()))
}
